<script setup lang="ts">
import {computed} from 'vue';import {ArrowRight} from '@element-plus/icons-vue';
import {fileBreadcrumbs} from './file-breadcrumbs';
const props=withDefaults(defineProps<{path:string;rootPath?:string;label?:string;rootLabel?:string;emptyPath?:string}>(),{rootPath:'',label:'文件路径',rootLabel:'云盘',emptyPath:'.'});const emit=defineEmits<{navigate:[string]}>();
const crumbs=computed(()=>fileBreadcrumbs(props.rootPath,props.path,props.rootLabel,props.emptyPath));
</script>
<template><div class="file-location-row"><nav class="file-location" :aria-label="label"><template v-for="(crumb,index) in crumbs" :key="index"><el-icon v-if="index" aria-hidden="true"><ArrowRight/></el-icon><button v-if="crumb.path!==null" type="button" :title="crumb.name" :aria-label="crumb.name" :aria-current="index===crumbs.length-1?'location':undefined" @click="emit('navigate',crumb.path)">{{crumb.name}}</button><span v-else :title="'超出当前授权目录范围'">{{crumb.name}}</span></template></nav><div class="file-location-extra"><slot/></div></div></template>
<style scoped>.file-location-row{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:nowrap;min-width:0;width:100%;box-sizing:border-box;min-height:44px;margin:12px 0}.file-location{display:flex;gap:6px;align-items:center;flex-wrap:nowrap;flex:1;overflow:hidden;min-width:0;font-size:13px}.file-location button{border:0;background:transparent;color:var(--mt-color-primary);font:inherit;min-height:44px;padding:4px 6px;max-width:100%;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}.file-location button[aria-current]{color:var(--mt-text-primary);font-weight:600}.file-location>span{color:var(--mt-text-muted);min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-location .el-icon{font-size:12px;flex:none}.file-location-extra{margin-left:auto;flex-shrink:0}.file-location-extra :deep(button){min-height:44px}</style>
